import { readFileSync } from "node:fs";
import * as z from "zod";

const Price = z
  .string()
  .regex(/^\d+\.\d{2}$/, "expected a price like 12.50")
  .transform((text) => Math.round(Number(text) * 100));

type PriceInput = z.input<typeof Price>;
//   ^? type PriceInput = string
type PriceOutput = z.output<typeof Price>;
//   ^? type PriceOutput = number

const lines = readFileSync(0, "utf8").trim().split("\n");
lines.forEach((line, i) => {
  const result = Price.safeParse(line);
  if (result.success) {
    console.log(`line ${i + 1}: ${result.data} cents`);
  } else {
    console.log(`line ${i + 1}: ${result.error.issues[0]?.message}`);
  }
});

import * as z from "zod";

const IsoDate = z.codec(z.iso.datetime(), z.date(), {
  decode: (text) => new Date(text),
  encode: (date) => date.toISOString(),
});

const Event = z.object({ name: z.string(), startsAt: IsoDate });

const event = Event.decode({ name: "Launch", startsAt: "2026-11-02T15:30:00Z" });
//    ^? const event: { name: string; startsAt: Date; }
const start = event.startsAt;
console.log(`${event.name} starts at ${start.getUTCHours()}:${start.getUTCMinutes()} UTC`);

const dayLater = new Date(start.getTime() + 24 * 60 * 60 * 1000);
const json = Event.encode({ ...event, startsAt: dayLater });
//    ^? const json: { name: string; startsAt: string; }
console.log(JSON.stringify(json));

const bad = Event.safeDecode({ name: "Launch", startsAt: "next Tuesday" });
if (!bad.success) {
  for (const issue of bad.error.issues) {
    console.log(`${issue.path.join(".")}: ${issue.message}`);
  }
}

