import { readFileSync } from "node:fs";
import * as z from "zod";

const Price = z
  .string()
  .regex(/^\d+\.\d{2}$/, "expected a price like 12.50")
  .transform((text) => Math.round(Number(text) * 100));

const IsoDate = z.codec(z.iso.datetime(), z.date(), {
  decode: (text) => new Date(text),
  encode: (date) => date.toISOString(),
});

export const PriceRow = z.object({
  sku: z.string().regex(/^[A-Z]{3}-\d{3}$/, "expected a SKU like MUG-001"),
  price: Price,
  available_from: IsoDate,
});

const [header = "", ...rows] = readFileSync(0, "utf8").trim().split("\n");
const columns = header.split(",");
rows.forEach((row, i) => {
  const cells = row.split(",");
  const record = Object.fromEntries(columns.map((name, c) => [name, cells[c]]));
  const result = PriceRow.safeParse(record);
  if (result.success) {
    console.log(JSON.stringify(result.data));
  } else {
    for (const issue of result.error.issues) {
      console.log(`line ${i + 2}: ${issue.path.join(".")}: ${issue.message}`);
    }
  }
});

